function dueRange(params) {
  const from = (params.get('dueFrom') || '').trim();
  const through = (params.get('dueThrough') || '').trim();
  if ((from && !validDueDate(from)) || (through && !validDueDate(through)) || (from && through && from > through)) {
    return { from: '', through: '' };
  }
  return { from, through };
}

